"""Twilio integration template — generates services/sms_client.py."""
from __future__ import annotations


def generate_twilio_client(output_dir=None, config: dict | None = None) -> str:
    """Return production-ready Twilio SMS/WhatsApp client code as a string."""
    return '''\
"""Twilio SMS/WhatsApp client — generated by AetherOS p04c_integration_codegen."""
from __future__ import annotations
import asyncio
import logging
import os
from functools import partial
from typing import Any, Dict

logger = logging.getLogger(__name__)


class SMSError(Exception):
    """Base error for SMS/WhatsApp operations."""


class SMSClient:
    """Async Twilio client for SMS and WhatsApp messaging."""

    def __init__(self) -> None:
        self._account_sid = os.getenv("TWILIO_ACCOUNT_SID", "")
        self._auth_token = os.getenv("TWILIO_AUTH_TOKEN", "")
        self._phone_number = os.getenv("TWILIO_PHONE_NUMBER", "")
        if not all([self._account_sid, self._auth_token, self._phone_number]):
            logger.warning(
                "Twilio env vars incomplete — TWILIO_ACCOUNT_SID, "
                "TWILIO_AUTH_TOKEN, TWILIO_PHONE_NUMBER must all be set"
            )

    def _get_client(self):
        """Lazy-import Twilio SDK."""
        try:
            from twilio.rest import Client
            return Client(self._account_sid, self._auth_token)
        except ImportError as exc:
            raise SMSError("twilio package not installed: pip install twilio") from exc

    async def send_sms(self, to: str, message: str) -> Dict[str, Any]:
        """Send an SMS message to the given E.164 phone number."""
        if not self._account_sid:
            logger.warning("SMS skipped — Twilio credentials not configured")
            return {"status": "skipped", "reason": "no_credentials"}
        try:
            client = self._get_client()
            loop = asyncio.get_event_loop()
            msg = await loop.run_in_executor(
                None,
                partial(
                    client.messages.create,
                    body=message,
                    from_=self._phone_number,
                    to=to,
                ),
            )
            logger.info("SMS sent to %s sid=%s status=%s", to, msg.sid, msg.status)
            return {"sid": msg.sid, "status": msg.status, "to": to}
        except Exception as exc:
            logger.warning("send_sms to %s failed: %s", to, exc)
            raise SMSError(str(exc)) from exc

    async def send_whatsapp(self, to: str, message: str) -> Dict[str, Any]:
        """Send a WhatsApp message. `to` must be in E.164 format (e.g. +1234567890)."""
        if not self._account_sid:
            logger.warning("WhatsApp skipped — Twilio credentials not configured")
            return {"status": "skipped", "reason": "no_credentials"}
        try:
            client = self._get_client()
            whatsapp_from = f"whatsapp:{self._phone_number}"
            whatsapp_to = f"whatsapp:{to}"
            loop = asyncio.get_event_loop()
            msg = await loop.run_in_executor(
                None,
                partial(
                    client.messages.create,
                    body=message,
                    from_=whatsapp_from,
                    to=whatsapp_to,
                ),
            )
            logger.info("WhatsApp sent to %s sid=%s status=%s", to, msg.sid, msg.status)
            return {"sid": msg.sid, "status": msg.status, "to": whatsapp_to}
        except Exception as exc:
            logger.warning("send_whatsapp to %s failed: %s", to, exc)
            raise SMSError(str(exc)) from exc


sms_client = SMSClient()
'''
